local UITeamMembersNode = Class("UITeamMembersNode")
function UITeamMembersNode:__init() 
    self._data = nil
    self._scale = 1
    self._cardCb = nil
    self._maxMembers = 0
    self.isIgnoreCardSize = false
end

function UITeamMembersNode:__delete()
    self._data = nil
    self._scale = 1
