end

function UITeamMembersNode:Start()
end

---Refresh 初始化
---@param data table  
---@param isTeamMember boolean 是否时队伍队员数据  
function UITeamMembersNode:Refresh(data, isTeamMember, scale, cardCb, isFillHp, upBuffData, isLimit, questId, showFetter,isIgnore)
    if not data then
        return
    end
    self._data = data
    self._upBuffData = upBuffData
    self._curQuestId = checkNumber(questId)
    self._maxMembers = teamComponent:GetMaxTeamMemberNum(self._curQuestId)

    if scale then
        self._scale = scale
    end
    self._cardCb = cardCb

    if isTeamMember then
        self:FillTeamMemberDatas(isFillHp, isLimit, showFetter)
    else
        self:FillCardDatas(isFillHp, isLimit, showFetter,isIgnore)
    end
end

--只绘制卡牌头像
function UITeamMembersNode:RefreshCardBase(data, scale, cardCb)
    if not data then
        return
    end
    self._data = data
    if scale then
        self._scale = scale
    end
    self._cardCb = cardCb

    local count = 1
    for k, v in pairs(self._data) do
        local go = self:GetCellByIndex(count)
        local vo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
        self:FillCardBase(go, vo)
        count = count + 1 
    end
end

--只绘制卡牌头像
