        count = count + 1 
    end
end

--调查的卡牌
function UITeamMembersNode:RefreshInvestigateCard(data, limitNum, scale, cardCb)
    if not data then
        return
    end
    self._data = data
    self._cardCb = cardCb
    if scale then
        self._scale = scale
    end
    limitNum = checkNumber(limitNum)

    local count = 1
    for k, v in pairs(self._data) do
        local go = self:GetCellByIndex(count)
        self:FillTeamMember(go, v)
        count = count + 1 
    end

    for i = 1, limitNum do
        local go = self:GetCellByIndex(count)
        self:FillTeamMember(go, nil , true )
        count = count + 1 
    end
end 

--刷新间隙
function UITeamMembersNode:RefreshSpacing(num)
    local group = self.Members.transform:GetComponent(typeof(HorizontalLayoutGroup))
    if group then
        group.spacing = checkNumber(num)
    end
end

--卡牌数据绘制
function UITeamMembersNode:FillCardDatas(isFillHp, isLimit, showFetter,isIgnore)
    local count = 1
    for k, v in pairs(self._data) do
        local go = self:GetCellByIndex(count)
        self:FillTeamMember(go, v, isLimit, showFetter,isIgnore)
        count = count + 1 
        
        if isFillHp then
            self:FillCardHpEnergy(go, v)
        end
    end

    if count <= self._maxMembers then        
        for i = count, self._maxMembers do
            local go = self:GetCellByIndex(i)
            self:FillTeamMember(go, nil, isLimit)
            count = count + 1
        end
    end
end

--队伍队员数据绘制
function UITeamMembersNode:FillTeamMemberDatas(isFillHp, isLimit, showFetter)
    for i = 1, self._maxMembers do
        local go = self:GetCellByIndex(i)
        self:FillTeamMember(go, self._data[i], isLimit, showFetter)

        if isFillHp then
            self:FillCardHpEnergy(go, self._data[i])
        end
    end
end

function UITeamMembersNode:FillTeamMember(go, data, isLimit, showFetter,isIgnore)
    if not go then
        return
    end
    ---@type UITeamMemberNode
    local scr = CfUtils.GetLuaScr(go, UITeamMemberNode)
    if scr then
        scr.isIgnoreCardSize = self.isIgnoreCardSize
        scr:Refresh(data, self._scale, self._cardCb, self._upBuffData)
        scr:FillBg(isLimit)
        if showFetter then
            scr:FillFettersInfo(data,isIgnore)
        end
    end
end

--只绘制卡牌头像
function UITeamMembersNode:FillCardBase(go, data)
    if not go or not data then
        ---@type UITeamMemberNode
        local scr = CfUtils.GetLuaScr(go, UITeamMemberNode)
        scr:FillBg(true)
        return
    end
    ---@type UITeamMemberNode
    local scr = CfUtils.GetLuaScr(go, UITeamMemberNode)
    if scr then
        scr:FillCardBase(data, self._scale, self._cardCb)
    end
end

function UITeamMembersNode:ResetCells()
    for index = 1, self.Members.transform.childCount do
        CfUtils.SetActive(self.Members.transform:GetChild(index - 1), false)
    end
end
    
function UITeamMembersNode:GetCellByIndex(index)
    local go = self.Members.transform:Find("Cell"..index)
    if not go then
        go = CfUtils.InstantiateGo(self.UITeamMemberNode, self.Members)
        go.name = "Cell"..index
    end
    return go
end

