function UITeamMembersNode:FillOneCardAliveState(data)
    if isNull(data) then
        return
    end
    local index = data.index
    local state = data.state
    local go = self:GetCellByIndex(index)
    ---@type UITeamMemberNode
    local scr = CfUtils.GetLuaScr(go, UITeamMemberNode)
